#include "pack_gpu.hpp"
#include <dxgi1_6.h>
#include <d3d12sdklayers.h>
#include <fstream>
#include <iostream>
#include <cmath>
#include <algorithm>
#include <bit>
using namespace arc_packet;
struct Input{uint32_t r[4];float transparency,fade,radius,alpha;uint32_t lod,stencil,pad0,pad1;};
struct Extra{float transparency;uint32_t lod,alpha;};
float half(uint32_t h){int e=(h>>10)&31,m=h&1023;return (h&32768?-1.f:1.f)*std::ldexp(float(m+(e?1024:0)),e?e-25:-24);}
int wmain(int argc,wchar_t** argv){try{
 if(argc!=4)return 2;std::ifstream f(argv[1],std::ios::binary|std::ios::ate);auto bytes=f.tellg();if(bytes<=0||bytes%48||bytes>65536*48)throw std::runtime_error("input bounds");std::vector<Input> input(size_t(bytes)/48);f.seekg(0);f.read((char*)input.data(),bytes);uint32_t n=uint32_t(input.size()),objects=0;for(auto& v:input)objects=std::max(objects,v.r[1]+1);if(objects>131072)throw std::runtime_error("object bounds");
 std::vector<uint32_t> records(n*4),obj(objects*64);std::vector<Extra> extra(objects);for(uint32_t i=0;i<n;++i){auto& v=input[i];memcpy(records.data()+i*4,v.r,16);uint32_t o=v.r[1]*64;obj[o+2]=v.stencil<<24;memcpy(obj.data()+o+11,&v.fade,4);memcpy(obj.data()+o+23,&v.radius,4);extra[v.r[1]]={v.transparency,v.lod,uint32_t(v.alpha<1)};}
 std::vector<uint32_t> expected;Result ref{};for(uint32_t i=0;i<n;++i){auto& v=input[i];uint32_t lod=(v.r[3]&255)==255?(v.lod&255):(v.r[3]&255);if(i==0||ref.groups[ref.count-1].mesh!=v.r[0]||ref.groups[ref.count-1].lod!=lod||ref.groups[ref.count-1].stencil!=v.stencil){if(ref.count==256)throw std::runtime_error("group budget");if(ref.count)ref.groups[ref.count-1].end=i;ref.groups[ref.count++]={v.r[0],lod,v.stencil,0,uint32_t(expected.size()),0,i,n};}auto& g=ref.groups[ref.count-1];float d=std::max(v.transparency,std::max(0.f,half(v.r[2]&65535)-v.fade)/v.radius);if(d>.99f)continue;if(d>0||v.alpha<1)g.alpha=1;uint32_t mask=v.r[2]>>16;while(mask){auto bit=std::countr_zero(mask);mask^=1u<<bit;expected.push_back((v.r[1]&0xffffff)|(bit<<24)|((uint32_t(std::max(0.f,d)*15)&15)<<28));++g.count;}}ref.words=uint32_t(expected.size());
 ComPtr<ID3D12Debug> dbg;if(GetEnvironmentVariableW(L"ARC_PACKET_DEBUG",nullptr,0)&&SUCCEEDED(D3D12GetDebugInterface(IID_PPV_ARGS(&dbg))))dbg->EnableDebugLayer();
 ComPtr<IDXGIFactory6> factory;check(CreateDXGIFactory2(0,IID_PPV_ARGS(&factory)));ComPtr<ID3D12Device>d;for(UINT i=0;;++i){ComPtr<IDXGIAdapter1>a;if(factory->EnumAdapterByGpuPreference(i,DXGI_GPU_PREFERENCE_HIGH_PERFORMANCE,IID_PPV_ARGS(&a))==DXGI_ERROR_NOT_FOUND)break;DXGI_ADAPTER_DESC1 desc{};a->GetDesc1(&desc);if(!(desc.Flags&DXGI_ADAPTER_FLAG_SOFTWARE)&&SUCCEEDED(D3D12CreateDevice(a.Get(),D3D_FEATURE_LEVEL_11_0,IID_PPV_ARGS(&d))))break;}if(!d)throw std::runtime_error("device");D3D12_COMMAND_QUEUE_DESC qd{};ComPtr<ID3D12CommandQueue>q;check(d->CreateCommandQueue(&qd,IID_PPV_ARGS(&q)));Worker w;w.init(d.Get(),q.Get(),argv[2]);
 auto object=w.buffer(obj.size()*4,D3D12_HEAP_TYPE_DEFAULT,D3D12_RESOURCE_STATE_COPY_DEST),side=w.buffer(extra.size()*12,D3D12_HEAP_TYPE_UPLOAD,D3D12_RESOURCE_STATE_GENERIC_READ),up=w.buffer(obj.size()*4,D3D12_HEAP_TYPE_UPLOAD,D3D12_RESOURCE_STATE_GENERIC_READ),out=w.buffer(uint64_t(n)*64,D3D12_HEAP_TYPE_DEFAULT,D3D12_RESOURCE_STATE_ALL_SHADER_RESOURCE,true);void* p{};D3D12_RANGE empty{};check(up->Map(0,&empty,&p));memcpy(p,obj.data(),obj.size()*4);check(side->Map(0,&empty,&p));memcpy(p,extra.data(),extra.size()*12);check(w.allocator->Reset());check(w.list->Reset(w.allocator.Get(),nullptr));w.list->CopyBufferRegion(object.Get(),0,up.Get(),0,obj.size()*4);w.barrier(object.Get(),D3D12_RESOURCE_STATE_COPY_DEST,D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);check(w.list->Close());ID3D12CommandList* c=w.list.Get();q->ExecuteCommandLists(1,&c);w.wait();
 std::ofstream csv(argv[3]);csv<<"iteration,records,groups,words,full_ms,copy_ms,record_ms,submit_ms,wait_ms,consume_ms,gpu_ms,gpu_upload_ms,gpu_return_ms\n";
 for(int i=-2;i<20;++i){Metrics m;Result got;try{got=w.run(records.data(),n,objects,true,object.Get(),side.Get(),out.Get(),m,i==-2);}catch(...){ComPtr<ID3D12InfoQueue> iq;if(SUCCEEDED(d.As(&iq))){for(UINT64 j=0;j<iq->GetNumStoredMessages();++j){SIZE_T z{};iq->GetMessage(j,nullptr,&z);std::vector<char>b(z);auto msg=(D3D12_MESSAGE*)b.data();iq->GetMessage(j,msg,&z);std::cerr<<msg->pDescription<<"\n";}}throw;}if(got.error||got.count!=ref.count||got.words!=ref.words||memcmp(got.groups,ref.groups,ref.count*sizeof(Group)))throw std::runtime_error("metadata mismatch");if(i==-2){void* v{};check(w.verify->Map(0,nullptr,&v));if(memcmp(v,expected.data(),expected.size()*4))throw std::runtime_error("output mismatch");w.verify->Unmap(0,nullptr);}csv<<i<<','<<n<<','<<got.count<<','<<got.words<<','<<m.full<<','<<m.copy<<','<<m.record<<','<<m.submit<<','<<m.wait<<','<<m.consume<<','<<m.gpu<<','<<m.gpu_upload<<','<<m.gpu_return<<'\n';}
 std::cout<<"exact_output_and_metadata=1 source_assisted_replay=1 frame_gain_measured=0\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
